supported_protocols = ['rrc', 's1ap', 'x2ap', 'm3ap', 'rrc5g', 'ngap', 'xnap', 'e1ap', 'f1ap']


def _parse_container(msg, container_protocol, container_type, key_to_find_container,
                     list_unique_key_path_above_required_key=None, upper_key_unique_requirements_tuple=None):
    """

    :param msg:
    :param container_protocol: protocol used in hex decoding
    :param container_type: container string used in hex decoding
    :param key_to_find_container: container string visible in logs
    :param list_unique_key_path_above_required_key:
    :param upper_key_unique_requirements_tuple:
    :return:
    """
    assert container_protocol in supported_protocols, 'Only supported protocols: {}'.format(supported_protocols)
    assert (list_unique_key_path_above_required_key is None and upper_key_unique_requirements_tuple is None) or \
           (list_unique_key_path_above_required_key is not None and upper_key_unique_requirements_tuple is not None), \
        "Both fields: list_unique_key_path_above_required_key," \
        " upper_key_unique_requirements_tuple must be specififed or left empty, not mixed!"

    if isinstance(msg, (ute_Message, ute_MessageField, ta_Message, ta_MessageField)):
        unique_key_path_for_container = key_to_find_container if list_unique_key_path_above_required_key is None \
            else list_unique_key_path_above_required_key
        return _parse_container_from_python_struct(msg, container_protocol, container_type, key_to_find_container,
                                                   unique_key_path_for_container, upper_key_unique_requirements_tuple)
    else:
        return _parse_container_from_string(msg, container_protocol, container_type, key_to_find_container)


def _parse_container_from_string(msg, container_protocol, container_type, key_to_find_container):
    error_logger = logging.getLogger('messaging.container.errors')
    match_key_to_find_container = re.compile(r"{}\s*:?\s*'([0-9a-fA-F]+)'H".format(key_to_find_container))
    ie_strings = re.findall(match_key_to_find_container, msg)
    hex_to_be_parsed = ""
    parsed_value = ""
    for ie_string in ie_strings:
        try:
            hex_to_be_parsed += "\n{}".format(ie_string)
            uesim_dump_string = UesimParser.UesimHexMsg(protocol=container_protocol,
                                                        pdu_type=container_type,
                                                        hex=ie_string).dump_for_uesim()
            parser = UesimParser()
            parsed_value += "\n{}".format(parser._convert_uesim_hex_msg2asn_value(uesim_dump_string))
        except UesimConverterError:
            pass
        except pyparsing.ParseException:
            pass
        except Exception as e:
            error_logger.debug('CONTAINER PARSING ERROR: Other exception occurred: {}'.format(e))
            error_logger.debug(traceback.format_exc())
    hex_to_be_parsed = None if hex_to_be_parsed == "" else hex_to_be_parsed
    parsed_value = None if parsed_value == "" else parsed_value
    return 0, hex_to_be_parsed, parsed_value


def _parse_container_from_python_struct(msg, container_protocol, container_type, key_to_find_container,
                                        unique_key_path_for_container, upper_key_unique_requirements_tuple):
    index = 0
    hex_to_be_parsed = ""
    parsed_value = None
    try:
        unique_value = _get_value_by_unique_key_path(msg, unique_key_path_for_container)
    except NotFoundKey:
        return None, unique_key_path_for_container, None
    if upper_key_unique_requirements_tuple is None or upper_key_unique_requirements_tuple == '':
        hex_to_be_parsed = unique_value
    else:
        assert isinstance(unique_value, list), 'Expected value is not a list'
        for c_index, container in enumerate(unique_value):
            found = _process_upper_container_with_reqs(container, upper_key_unique_requirements_tuple)
            if found:
                hex_to_be_parsed = container.get_value_by_unique_key(key_to_find_container)
                index = c_index
                break
    parsed_value = _parse_hex_value(hex_to_be_parsed=hex_to_be_parsed,
                                    container_protocol=container_protocol,
                                    container_type=container_type)
    return index, key_to_find_container, parsed_value


def _get_value_by_unique_key_path(container, unique_key_path):
    if not isinstance(unique_key_path, list):
        return container.get_value_by_unique_key(unique_key_path)
    for key in unique_key_path:
        if isinstance(key, int):
            container = container[key]
        else:
            container = container.get_value_by_unique_key(key)
    return container


def _process_upper_container_with_reqs(container, upper_key_unique_requirements_tuple):
    found = True
    for (req_key, req_val) in upper_key_unique_requirements_tuple:
        if container.get_value_by_unique_key(req_key) != req_val:
            found = False
    return found


def _parse_hex_value(hex_to_be_parsed, container_protocol, container_type):
    match = re.search(r'(?:0x)?([0-9a-hA-H]+)', hex_to_be_parsed)
    if match:
        hex_value = match.group(1)
        try:
            parsed_value = eval("parse_{}_container(container_type, hex_value)".format(str(container_protocol).lower()))
        except pyparsing.ParseException as e:
            raise UesimConverterError('Parsing exception: {}'.format(e))
        return parsed_value
    else:
        return None


# UECapabilityInformation
def parse_ue_eutra_capability_from_rrc(msg):
    """
    RRC protocol specific function to avoid UE capabilities duplication while parsing with raw_log_parser.py
    :param msg:
    :return: tuple (index_where_to_put_value, key, parsed_value)
    """
    if isinstance(msg, (ute_Message, ute_MessageField, ta_Message, ta_MessageField)):
        return parse_ue_eutra_capability(msg)
    else:
        return (0, None, None)  # uesim-dump parses capabilities by default - we don't want to duplicate them


