# UECapabilityInfoIndication, InitialContextSetupRequest
def parse_ue_radio_capability_as_ue_radio_access_capability_information(msg):
    """

    :param msg:
    :return: tuple (index_where_to_put_value, key, parsed_value)

    """
    possible_transparent_containers = ['UERadioAccessCapabilityInformation',
                                       'UERadioAccessCapabilityInformation-NB']

    parsed_container = (None, None, None)
    error_logger = logging.getLogger('messaging.container.errors')
    for possible_container in possible_transparent_containers:
        try:
            parsed_container = _parse_container(msg, 'rrc', possible_container, 'UERadioCapability')
            if len(parsed_container) == 3 and parsed_container[2] is not None:
                break
        except UesimConverterError:
            pass
        except Exception as e:
            error_logger.debug('CONTAINER PARSING ERROR: Other exception occurred: {}'.format(e))
            error_logger.debug(traceback.format_exc())
    return parsed_container


