def parse_ngap_source_to_target(msg):
    """
    :param msg:
    :return: tuple (index_where_to_put_value,    key, parsed_value)
    """
    possible_containers_in_message = ['SourceToTarget-TransparentContainer',
                                      'Source-ToTarget-TransparentContainer']
    possible_transparent_containers_to_parse = ['SourceeNB-ToTargeteNB-TransparentContainer',
                                                'SourceNGRANNode-ToTargetNGRANNode-TransparentContainer']
    parsed_container = (None, None, None)
    error_logger = logging.getLogger('messaging.container.errors')
    for possible_container_in_message in possible_containers_in_message:
        for possible_container in possible_transparent_containers_to_parse:
            try:
                parsed_container = _parse_container(msg, 'ngap', possible_container, possible_container_in_message)
            except UesimConverterError:
                pass
            except Exception as e:
                error_logger.debug('CONTAINER PARSING ERROR: Other exception occurred: {}'.format(e))
                error_logger.debug(traceback.format_exc())

    return parsed_container


