def parse_nr_target_rat_message_container(msg):
    """

    :param msg:
    :return: tuple (index_where_to_put_value, key, parsed_value)
    """
    error_logger = logging.getLogger('messaging.container.errors')
    parsed_container = (None, None, None)
    try:
        parsed_container = _parse_container(msg, 'rrc5g', 'RRCReconfiguration', 'targetRAT-MessageContainer')
    except UesimConverterError:
        pass
    except Exception as e:
        error_logger.debug('CONTAINER PARSING ERROR: Other exception occurred: {}'.format(e))
        error_logger.debug(traceback.format_exc())
    return parsed_container


def _get_parsers_for_measurement_timing_configuration(message_structure):
    if isinstance(message_structure, (ute_Message, ute_MessageField, ta_Message, ta_MessageField)):
        pass
    parsers_list = []
    possible_parent_keys = [parent_key for parent_key in ['servedNRCellInfo', 'nRNeighbourInfo'] if parent_key in message_structure]

    for parent_key in possible_parent_keys:
        if isinstance(message_structure, (ute_Message, ute_MessageField, ta_Message, ta_MessageField)):
            number_of_measurementTimingConfiguration = len(message_structure.get_all_values_by_key(parent_key))
            parsers_list.extend([partial(parse_measurement_timing_configuration_with_index_given, index, parent_key)
                                 for index in range(number_of_measurementTimingConfiguration)])
        else:
            number_of_measurementTimingConfiguration = len(re.findall(parent_key, message_structure))
            parsers_list.extend([partial(parse_measurement_timing_configuration_with_index_given, index, parent_key)
                                 for index in range(number_of_measurementTimingConfiguration)])
    return parsers_list


