def get_containers_for_msg(message_type, message_structure):
    """
    :param message_type:
    :param message_structure:
    :return:
    """
    containers_for_msg = containers[message_type]
    if isinstance(containers_for_msg, list):
        return containers_for_msg
    else:
        return containers_for_msg(message_structure)


def does_message_contain_parsable_containers(message_type):
    """
    :param message_type:
    :return:
    """
    return message_type in containers
